import { RefreshCw, AlertCircle } from 'lucide-react'

/**
 * DashboardInsight — The plain-English process analysis generated by Gemini, set as the page's lead statement.
 */
export default function DashboardInsight({ insight, isLoading, isError, onRefresh }) {
  return (
    <div className="rounded-card border border-ai-border border-l-4 border-l-primary bg-ai-bg p-5 sm:p-6 animate-fade-in-up">
      <div className="flex items-center justify-between gap-3 mb-3">
        <h2 className="font-head text-sm font-semibold text-primary">AI summary</h2>

        <button
          onClick={onRefresh}
          disabled={isLoading}
          title="Refresh summary"
          className="text-xs font-medium text-muted hover:text-primary flex items-center gap-1.5 transition-colors cursor-pointer disabled:opacity-50"
        >
          <RefreshCw size={13} className={isLoading ? 'animate-spin text-primary' : ''} />
          <span>{isLoading ? 'Updating...' : 'Refresh'}</span>
        </button>
      </div>

      {isLoading ? (
        <div className="space-y-2.5 py-1 animate-pulse">
          <div className="h-5 bg-primary/15 rounded-md w-11/12" />
          <div className="h-5 bg-primary/10 rounded-md w-4/5" />
        </div>
      ) : isError ? (
        <div className="flex items-center gap-2 text-xs text-danger py-1">
          <AlertCircle size={15} />
          <span>Could not load the AI summary right now. Click refresh to retry.</span>
        </div>
      ) : (
        <p className="font-editorial text-lg sm:text-xl text-text leading-snug max-w-4xl">
          {insight?.text || insight || 'No process insights available for this dataset.'}
        </p>
      )}
    </div>
  )
}
